import { createApp } from "vue";
import { createRouter, createWebHistory } from "vue-router";
import App from "./App.vue";
import FirstTour from "./components/FirstTour.vue";
import SecondTour from "./components/SecondTour.vue";

const routes = [
  { path: "/firstTour", name: "FirstTour", component: FirstTour },
  { path: "/SecondTour", name: "SecondTour", component: SecondTour },
];

const router = createRouter({
  history: createWebHistory("/Names/"), // Установите здесь базовый путь
  routes,
});

const app = createApp(App);
app.use(router);
app.mount("#app");
